import { useState } from "react";

export default function App() {
  return (
    // group related state
    // avoid contradictions?
    <>
      wow
    </>
  );
}




initialList = {
    root: {upperParent: [1,2]},
    1: { list: "1", child: ["a"] },
    a: { subList: ["a1","a2","a3"] },
    "a1": { no: "a1" },
    "a2": { no: "a2" },
    "a3": { no: "a3" },
    2: { list: "2", child: ["b", "c", "d"] },
    "b": { no: "b" },
    "c": { no: "c" },
    "d": { no: "d" },}
    // a = {1: "wow", b: "wow", "1": "wow"}
    // console.log(a.b); console.log(a[1]); console.log(a["1"])
function AvoidDeeplyNested() {
  const [list, setList] = useState({
    root: {upperParent: [1,2]},
    1: { list: "1", child: ["a"] },
    a: { subList: ["a1","a2","a3"] },
    "a1": { no: "a1" },
    "a2": { no: "a2" },
    "a3": { no: "a3" },
    2: { list: "2", child: ["b", "c", "d"] },
    "b": { no: "b" },
    "c": { no: "c" },
    "d": { no: "d" },
  });

  
  return (
    <>
      d
    </>
  );
}
